}


.main {
  .safeArea {
    .lo-container {
      background-image: url(data:image/png;base64,);

      animation: showQ 0.7s normal;

      .logo {
        background-image: url(data:image/png;base64,);
      }

      .side-navgations {
        .border-navgations {
          background-image: url(data:image/png;base64,);

          .icon {
            &.home {
              background-image: url(data:image/png;base64,);

              &:hover {
                background-image: url(data:image/png;base64,);
              }

              &.selected {
                background-image: url(data:image/png;base64,);
              }
            }

            &.quiz {
              background-image: url(data:image/png;base64,);

              &:hover {
                background-image: url(data:image/png;base64,);
              }

              &.selected {
                background-image: url(data:image/png;base64,);
              }
            }

            &.slideShow {
              background-image: url(data:image/png;base64,);

              &:hover {
                background-image: url(data:image/png;base64,);
              }

              &.selected {
                background-image: url(data:image/png;base64,);
              }
            }

            &.exit {
              background-image: url(data:image/png;base64,);
            }

            &.zoom {
              background-image: url(data:image/png;base64,);
            }
          }
        }
      }

      .content {


        .title {
          background-image: url(data:image/png;base64,);
        }

        .border-content {

          .StartPage {


            .start {
              background-image: url(data:image/png;base64,);

              &:hover {
                background-image: url(data:image/png;base64,);

              }

              &:active {
                background-image: url(data:image/png;base64,);

              }
            }
          }

          .chooseQuestion {
            .chooses {
              .choose {
                background-image: url(data:image/png;base64,);

                &.true {
                  background-image: url(data:image/png;base64,) !important;
                }

                &.false {
                  background-image: url(data:image/png;base64,) !important;
                }

                &.select {
                  background-image: url(data:image/png;base64,) !important;
                }
              }
            }
          }

          .DragQuestion {
            .drag {
              background-image: url(data:image/png;base64,);
            }

            .drop {
              &.wrong {
                .drag {
                  background-image: url(data:image/png;base64,);
                }
              }

              &.correct {
                .drag {
                  background-image: url(data:image/png;base64,);
                }
              }
            }
          }

          .inline-passage-drag-question {
            .inline-passage-drag-card {
              background-image: url(data:image/png;base64,);
            }

            .inline-passage-drop-zone {
              // background-image: url(data:image/png;base64,);

              &.is-wrong {
                background-image: url(data:image/png;base64,) !important;

              }

              &.is-correct {
                background-image: url(data:image/png;base64,) !important;

              }

              &.is-filled {
                background-image: url(data:image/png;base64,);

              }
            }
          }

          .matchQuestion {
            .columnRight {
              .row-text {
                &.div-txt {
                  background-image: url(data:image/png;base64,)
                }

                .cointDrag {
                  background-image: url(data:image/png;base64,);

                  .false {
                    background-image: url(data:image/png;base64,);
                  }

                  .true {
                    background-image: url(data:image/png;base64,) !important;
                  }
                }
              }
            }

            .columnLeft {
              .row-text {
                &.div-txt {
                  background-image: url(data:image/png;base64,)
                }

                .cointDrag {
                  background-image: url(data:image/png;base64,);

                  .false {
                    background-image: url(data:image/png;base64,);
                  }

                  .true {
                    background-image: url(data:image/png;base64,) !important;
                  }
                }
              }
            }
          }

          // .question {
          //     background-image: url(data:image/png;base64,);

          // }

          .sumbit {
            background-image: url(data:image/png;base64,);

            &.dimmed {
              background-image: url(data:image/png;base64,);
            }

            &:hover {
              background-image: url(data:image/png;base64,);
            }
          }

          .feedBack {
            background-image: url(data:image/png;base64,);

            .feedBackImg {
              .status {
                &.happy {
                  background-image: url(data:image/png;base64,);
                }

                &.sad {
                  background-image: url(data:image/png;base64,);
                }

                &.happygirl {
                  background-image: url(data:image/png;base64,);
                }

                &.happyboy {
                  background-image: url(data:image/png;base64,);
                }

                &.sadgirl {
                  background-image: url(data:image/png;base64,);
                }

                &.sadboy {
                  background-image: url(data:image/png;base64,);
                }
              }
            }

            .icon {
              &.next {
                background-image: url(data:image/png;base64,);

                &:hover {
                  background-image: url(data:image/png;base64,);
                }
                   &:active {
                  background-image: url(data:image/png;base64,);
                }
              }

              &.reload {
                background-image: url(data:image/png;base64,);

                &:hover {
                  background-image: url(data:image/png;base64,);
                }

                &:active {
                  background-image: url(data:image/png;base64,);
                }
              }

              &.home {
              background-image: url(data:image/png;base64,);

                &:hover {
                  background-image: url(data:image/png;base64,);
                }

                &:active {
                  background-image: url(data:image/png;base64,);
                }
              }
            }
          }
        }
      }
    }

  }

  &.activestart {
    #lo-container {
      &::after {
        content          : "";
        position         : absolute;
        width            : 10vw;
        height           : 3vw;
        right            : 0;
        bottom           : 0;
        background-size  : contain;
        background-repeat: no-repeat;
        background-image : url(data:image/png;base64,);
      }
    }
  }
}

.sound {
  &.play {
    background-image: url(data:image/png;base64,) !important;
  }

  &.pause {
    background-image: url(data:image/png;base64,);
  }

  &:hover {
    background-image: url(data:image/png;base64,);
  }
}



.main {
  &.eng {
    .safeArea {
      .lo-container {
        .content {
          .border-content {
            .feedBack {


              .icon {
                &.next {
                  background-image: url(data:image/png;base64,);

                  &:hover {
                    background-image: url(data:image/png;base64,);
                  }
                }
              }
            }
          }
        }
      }
    }
  }
}